"""Cross-language event projection oracle, generated by native offline runs."""

import json
from pathlib import Path
from tempfile import TemporaryDirectory
from threading import Event

from agenttinker.core.projection import project_events
from agenttinker.m0.synthetic import SyntheticModel
from agenttinker.packages.exporting import export_run
from agenttinker.packages.models import canonical
from agenttinker.runtime.service import DocumentRunRequest, ForkRequest, RunRequest, RunService
from agenttinker.storage.packages import SQLitePackageStore
from agenttinker.storage.sqlite import SQLiteEventStore


def capture(service, run_id):
    view = service.wait(run_id)
    with SQLiteEventStore(service.database) as store:
        events = store.events(run_id)
    return {
        "events": [event.model_dump(mode="json") for event in events],
        "prefixes": [
            project_events(events[:index]).model_dump(mode="json")
            for index in range(1, len(events) + 1)
        ],
        "view": view.model_dump(mode="json"),
    }


def main():
    result = {}
    with TemporaryDirectory(prefix="agenttinker-events-") as directory:
        with RunService(Path(directory) / "native.sqlite") as service:
            for limit, name in ((0, "failed"), (1, "retried")):
                created, _ = service.submit(
                    RunRequest(
                        mode="synthetic",
                        task="浏览器校验：比较虚构发布说明",
                        policy={"tool_retry_limit": limit},
                    ),
                    name,
                )
                result[name] = capture(service, created.run.run_id)
            source = service.get(result["failed"]["view"]["run"]["run_id"])
            forked, _ = service.fork(
                source.run.run_id,
                ForkRequest(
                    source_checkpoint_id=source.checkpoints[0].checkpoint_id,
                    patch={"tool_retry_limit": 1},
                ),
                "forked",
            )
            result["forked"] = capture(service, forked.run.run_id)
            document, _ = service.submit_document(DocumentRunRequest(mode="synthetic"), "document")
            result["document"] = capture(service, document.run.run_id)
            document = service.get(document.run.run_id)
            expanded, _ = service.fork(
                document.run.run_id,
                ForkRequest(
                    source_checkpoint_id=document.checkpoints[0].checkpoint_id, patch={"top_k": 3}
                ),
                "document_forked",
            )
            result["document_forked"] = capture(service, expanded.run.run_id)
            with SQLitePackageStore(service.database) as store:
                imported, _ = store.import_data(
                    canonical(export_run(service.database, expanded.run.run_id)), "imported"
                )
            result["imported"] = capture(service, imported.root_run_id)
            v2, _ = service.submit_document(
                DocumentRunRequest(mode="synthetic", agent_version="2"), "document_v2"
            )
            result["document_v2"] = capture(service, v2.run.run_id)
            v2 = service.get(v2.run.run_id)
            v2_branch, _ = service.fork(
                v2.run.run_id,
                ForkRequest(
                    source_checkpoint_id=v2.checkpoints[0].checkpoint_id, patch={"top_k": 3}
                ),
                "document_v2_forked",
            )
            result["document_v2_forked"] = capture(service, v2_branch.run.run_id)
            with SQLitePackageStore(service.database) as store:
                imported_v2, _ = store.import_data(
                    canonical(export_run(service.database, v2_branch.run.run_id)), "imported_v2"
                )
            result["imported_v2"] = capture(service, imported_v2.root_run_id)
        entered, release = Event(), Event()

        class Gated(SyntheticModel):
            def complete(self, messages):
                entered.set()
                if not release.wait(5):
                    raise TimeoutError("offline_fixture_gate")
                return super().complete(messages)

        with RunService(
            Path(directory) / "cancel.sqlite", model_factory=lambda _: Gated()
        ) as service:
            try:
                created, _ = service.submit(
                    RunRequest(mode="synthetic", task="取消后的在途观测"), "cancel"
                )
                if not entered.wait(3):
                    raise TimeoutError("offline_fixture_start")
                service.cancel(created.run.run_id)
            finally:
                release.set()
            result["cancelled"] = capture(service, created.run.run_id)
    print(json.dumps(result))


if __name__ == "__main__":
    main()
